from pathlib import Path
from PIL import Image,ImageDraw,ImageOps,ImageFilter
import numpy as np,json,hashlib
ROOT=Path(__file__).resolve().parent
SRC=ROOT.parent/'historical'
items=[]

def make(name,source,points,maxdim,anchors,notes,range_levels=None):
 im=Image.open(SRC/source).convert('RGB')
 xs=[p[0] for p in points];ys=[p[1] for p in points]
 box=(max(0,min(xs)-8),max(0,min(ys)-8),min(im.width,max(xs)+9),min(im.height,max(ys)+9))
 im=im.crop(box);m=Image.new('L',im.size,0)
 ImageDraw.Draw(m).polygon([(x-box[0],y-box[1]) for x,y in points],fill=255)
 ar=np.asarray(im.convert('L')).astype(np.float32);valid=np.asarray(m)>128
 lo,hi=np.percentile(ar[valid],[1.5,99]) if range_levels is None else range_levels
 norm=np.clip((ar-lo)/(hi-lo),0,1)
 # Gentle sepia tint retains all original engraving detail and material texture.
 dark=np.array([48,34,24.]);light=np.array([230,213,179.])
 rgb=np.uint8(np.clip(dark[None,None,:]+norm[:,:,None]*(light-dark)[None,None,:],0,255))
 rgba=Image.fromarray(rgb,'RGB');rgba.putalpha(m)
 scale=min(1,maxdim/max(rgba.size));size=(round(rgba.width*scale),round(rgba.height*scale))
 rgba=rgba.resize(size,Image.Resampling.LANCZOS)
 # Remove subpixel opacity dust outside the intentional hand-traced shape.
 a=np.asarray(rgba.getchannel('A')).copy();a[a<3]=0;rgba.putalpha(Image.fromarray(a))
 out=ROOT/(name+'.png');rgba.save(out,optimize=True)
 trans={k:{'pixel':[round((p[0]-box[0])*scale,1),round((p[1]-box[1])*scale,1)],'normalized':[round((p[0]-box[0])/im.width,5),round((p[1]-box[1])/im.height,5)]} for k,p in anchors.items()}
 items.append({'name':name,'path':str(out),'source_path':str(SRC/source),'source_crop_box':box,'width':size[0],'height':size[1],'anchors':trans,'mask_method':'Manually traced silhouette polygon against source pixels; antialiasing from Lanczos resampling. No generative reinterpretation.','color_treatment':{'method':'Original luminance mapped to restrained sepia','black_rgb':dark.tolist(),'white_rgb':light.tolist(),'source_luminance_low':float(lo),'source_luminance_high':float(hi)},'mask_points_source_pixels':points,'notes':notes,'sha256':hashlib.sha256(out.read_bytes()).hexdigest()})
 return rgba

