# Checkerboard QA contact sheet. Art is shown at fit scale, without simulated stage lighting.
w,h=1800,1350;sheet=Image.new('RGB',(w,h),(223,214,197));draw=ImageDraw.Draw(sheet)
for i,it in enumerate(items):
 x=(i%3)*600;y=(i//3)*675
 for yy in range(y+50,y+630,20):
  for xx in range(x+10,x+590,20):
   draw.rectangle((xx,yy,xx+19,yy+19),fill=(214,210,199) if ((xx-x)//20+(yy-y)//20)%2 else (246,242,232))
 im=Image.open(it['path']);im.thumbnail((556,555))
 sheet.paste(im,(x+(600-im.width)//2,y+65+(550-im.height)//2),im)
 draw.text((x+18,y+15),it['name']+'  '+str(it['width'])+' x '+str(it['height']),fill=(50,36,25))
 draw.text((x+18,y+641),'RGBA / original engraving / traced contour',fill=(70,56,39))
sheet.save(ROOT/'cutouts_contact_sheet.jpg',quality=94)
for it in items:print(it['name'],it['width'],it['height'],it['anchors'])
